@Component("promotion-subscriber")
public class PromotionSubscriber extends BaseSubscriber {

	public PromotionSubscriber() {
	}
	
    public SubscriptionQueryResult<List<Promotion>, Promotion> promotionSubscribe() {
        return queryGateway
                .subscriptionQuery(new FindAllPromotionQuery(), 
                		ResponseTypes.multipleInstancesOf(Promotion.class),
                		ResponseTypes.instanceOf(Promotion.class));
    }

    public SubscriptionQueryResult<Promotion, Promotion> promotionSubscribe(@DestinationVariable UUID promotionId) {
        return queryGateway
                .subscriptionQuery(new FindPromotionQuery(new LoadPromotionFilter(promotionId)), 
                		ResponseTypes.instanceOf(Promotion.class),
                		ResponseTypes.instanceOf(Promotion.class));
    }





}

